-- =============================================================================
-- 513 — LE CAHIER D'EXERCICES DE 1RE (partie 1)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 513 --niveau 1re --fichiers allemand.jumelles-2 --suffixe 1 > supabase/contenu/513_exercices_1re_1.sql
--
-- 21 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   allemand.jumelles-2     21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui est le plus grand ?","competence":"lire-tableau","situation":"Trois élèves de l’équipe de volley ont été mesurés par le professeur de sport. Il note leur âge et leur taille.","documents":[{"id":"equipe","type":"tableau","titre":"L’équipe de volley","colonnes":["Name","Alter","Größe (cm)"],"lignes":[["Lena",13,158],["Tim",15,172],["Mia",15,165]],"enteteLignes":true,"source":"Données inventées pour l’exercice"}],"questions":[{"enonce":"D’après le tableau, quelle phrase est juste ?","aide":"Compare les tailles de Tim et de Lena, et regarde le mot qui suit *größer*.","type":"choix","options":[{"id":"a","texte":"Tim ist größer als Lena"},{"id":"b","texte":"Mia ist so groß wie Tim"},{"id":"c","texte":"Tim ist größer wie Lena"},{"id":"d","texte":"Lena ist größer als Tim"}],"multiple":false},{"enonce":"Complète : « Lena est plus jeune que Tim. »","aide":"Une inégalité s’exprime avec comparatif + ...","type":"trous","segments":["Lena ist jünger ",0," Tim."],"banque":["so","mehr","als","wie"]},{"enonce":"Complète d’après les âges : « Mia est plus âgée que Lena. »","aide":"*alt* prend un Umlaut au comparatif.","type":"trous","segments":["Mia ist ",0," als Lena."],"banque":["alter","mehr alt","älteres","älter"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"**Tim ist größer als Lena** : Tim mesure 172 cm, Lena 158 cm. Après un comparatif, on emploie *als*, jamais *wie*."},{"cle":{"type":"trous","trous":[["als"]]},"affichage":"als","explication":"**Lena ist jünger als Tim.** Supériorité ou infériorité : comparatif + **als**."},{"cle":{"type":"trous","trous":[["alter"]]},"affichage":"älter","explication":"**Mia ist älter als Lena** : Mia a 15 ans, Lena 13 ; *alt → älter*, avec Umlaut."}]$ex$::jsonb),
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux smartphones à comparer","competence":"lire-tableau","situation":"Yasmin hésite entre deux smartphones. Elle compare leur prix, leur poids et la durée de leur batterie.","documents":[{"id":"phones","type":"tableau","titre":"Zwei Smartphones","colonnes":["","Modell A","Modell B"],"lignes":[["Preis (€)",300,450],["Gewicht (g)",160,140],["Akku (h)",20,30]],"enteteLignes":true,"source":"Données inventées pour l’exercice"}],"questions":[{"enonce":"De combien d’euros le modèle B est-il plus cher que le modèle A ?","aide":"Soustrais les deux prix.","type":"nombre","unite":"€"},{"enonce":"Complète : « Le modèle A est moins cher que le modèle B. »","aide":"Adjectif + -er, sans mot supplémentaire.","type":"trous","segments":["Modell A ist ",0," als Modell B."],"banque":["billiger","billigere","mehr billig","billig"]},{"enonce":"Quelle phrase est FAUSSE d’après le tableau ?","aide":"Cherche la phrase qui contredit un prix, un poids ou une durée du tableau.","type":"choix","options":[{"id":"a","texte":"Modell B ist so teuer wie Modell A"},{"id":"b","texte":"Modell A ist billiger als Modell B"},{"id":"c","texte":"Modell A ist nicht so leicht wie Modell B"},{"id":"d","texte":"Modell B ist leichter als Modell A"}],"multiple":false},{"enonce":"Remets en ordre : « Le modèle B est plus cher que le modèle A. » La phrase commence par Modell B.","aide":"Comparatif, puis *als* et le second terme.","type":"ordre","items":[{"id":"a","texte":"Modell A"},{"id":"b","texte":"ist"},{"id":"c","texte":"als"},{"id":"d","texte":"Modell B"},{"id":"e","texte":"teurer"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":150,"tolerance":0},"affichage":"150 €","explication":"**150 €** : 450 − 300 = 150. On écrit *Modell B ist teurer als Modell A*."},{"cle":{"type":"trous","trous":[["billiger"]]},"affichage":"billiger","explication":"**Modell A ist billiger als Modell B.** Le comparatif se forme avec **-er** : on n’emploie jamais *mehr* devant un adjectif."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Modell B ist so teuer wie Modell A** est fausse : B coûte 450 €, A 300 €. Les trois autres correspondent au tableau."},{"cle":{"type":"ordre","ids":["d","b","e","c","a"]},"explication":"**Modell B ist teurer als Modell A.** Structure : sujet + *ist* + comparatif + **als** + second terme."}]$ex$::jsonb),
  ('e9d46a34-f937-5cdd-b468-66f1b302908f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Mon allemand s’améliore","competence":"argumenter","situation":"Clara tient un petit carnet de ses révisions d’allemand. Elle a tracé son temps de travail par semaine et raconte ses progrès dans une lettre.","documents":[{"id":"lernzeit","type":"graphique","forme":"barres","titre":"Meine Lernzeit pro Tag","categories":["Woche 1","Woche 2","Woche 3","Woche 4"],"series":[{"nom":"Minuten","valeurs":[15,25,40,55],"teinte":"turquoise"}],"axeY":{"titre":"Lernzeit","unite":"Minuten","min":0,"max":60,"pas":10},"axeX":{"titre":"Woche"},"valeurs":false,"source":"Données inventées pour l’exercice"},{"id":"brief","type":"texte","genre":"lettre","titre":"Hallo Lena","blocs":["Ich lerne jede Woche länger Deutsch. Mein älterer Bruder Paul lernt mehr als ich, aber ich verstehe schon viel."],"source":"Lettre écrite pour l’exercice"}],"questions":[{"enonce":"Touche la semaine pendant laquelle Clara a travaillé le plus longtemps.","aide":"Cherche la barre la plus haute.","type":"zone","document":"lernzeit","multiple":false},{"enonce":"Combien de minutes de plus par jour Clara travaille-t-elle en semaine 4 qu’en semaine 1 ?","aide":"Lis les deux barres, puis soustrais.","type":"nombre","unite":"minutes"},{"enonce":"Touche le comparatif qui porte, en plus, une terminaison de déclinaison.","aide":"Il est devant un nom et se termine par -er.","type":"zone","document":"brief","multiple":false},{"enonce":"Quelle phrase compare correctement les semaines 4 et 2 ?","aide":"Après un comparatif, on emploie *als*, et *mehr* ne se place jamais devant un adjectif.","type":"choix","options":[{"id":"a","texte":"In Woche 4 lerne ich so länger als in Woche 2"},{"id":"b","texte":"In Woche 4 lerne ich mehr lang als in Woche 2"},{"id":"c","texte":"In Woche 4 lerne ich länger als in Woche 2"},{"id":"d","texte":"In Woche 4 lerne ich länger wie in Woche 2"}],"multiple":false},{"enonce":"Remets en ordre : « Plus Paul s’exerce en allemand, mieux il parle. » La phrase commence par Je mehr Deutsch.","aide":"Après *je…*, le verbe est à la fin de la proposition ; après *desto…*, le verbe est en deuxième position.","type":"ordre","items":[{"id":"a","texte":"desto besser"},{"id":"b","texte":"spricht er"},{"id":"c","texte":"Paul"},{"id":"d","texte":"übt,"},{"id":"e","texte":"Je mehr Deutsch"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"**Woche 4** : environ 55 minutes par jour, c’est la barre la plus haute."},{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 minutes","explication":"**40 minutes** : 55 − 15 = 40. *In Woche 4 lerne ich länger als in Woche 1.*"},{"cle":{"type":"zone","ids":["m7"]},"explication":"**älterer** : *alt → älter* (comparatif), puis *-er* (terminaison du masculin nominatif après *mein*) : *mein älterer Bruder*."},{"cle":{"type":"choix","ids":["c"]},"explication":"**länger als** : adjectif + **-er**, puis *als*. *wie* sert à l’égalité (*so lang wie*), et *mehr* ne traduit pas « plus » devant un adjectif."},{"cle":{"type":"ordre","ids":["e","c","d","a","b"]},"explication":"**Je mehr Deutsch Paul übt, desto besser spricht er.** Dans la première partie le verbe est rejeté en fin de proposition ; après *desto + comparatif*, il vient aussitôt, devant le sujet."}]$ex$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le désordre de Lena","competence":"comprendre-langue","situation":"Lena range sa chambre avant de partir. Un court texte raconte où se trouvent ses affaires et où elle les met.","documents":[{"id":"zimmer","type":"texte","genre":"recit","titre":"Lenas Zimmer","blocs":["Das Buch liegt auf dem Tisch. Eine Katze sitzt unter dem Stuhl. Lena legt ein Heft auf den Tisch. Dann geht sie in die Küche."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles au datif : ils répondent à la question « wo ? ».","aide":"Le livre et la chatte ne bougent pas.","type":"zone","document":"zimmer","multiple":true},{"enonce":"Touche les deux articles à l’accusatif : ils répondent à la question « wohin ? ».","aide":"Lena met le cahier quelque part et se déplace.","type":"zone","document":"zimmer","multiple":true},{"enonce":"Complète : « Le téléphone est sur le lit. »","aide":"*liegt* indique un lieu, pas un déplacement.","type":"trous","segments":["Das Handy liegt auf ",0," Bett."],"banque":["dem","das","den","die"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m10"]},"explication":"**dem** (deux fois) : *auf dem Tisch*, *unter dem Stuhl* décrivent un lieu où l’on est : datif."},{"cle":{"type":"zone","ids":["m17","m23"]},"explication":"**den** et **die** : *auf den Tisch*, *in die Küche* disent où l’on va ou où l’on pose quelque chose : accusatif."},{"cle":{"type":"trous","trous":[["dem"]]},"affichage":"dem","explication":"**auf dem Bett** : *wo ?* donne le datif ; *Bett* est neutre, donc *dem*."}]$ex$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le déménagement","competence":"manier-langue","situation":"Eva et Max emménagent dans un nouvel appartement. Chaque objet doit être posé au bon endroit : ils parlent tantôt d’un mouvement, tantôt d’un lieu.","documents":[{"id":"umzug","type":"dialogue","modele":"sms","titre":"Umzug","participants":[{"nom":"Eva","emoji":"👧","cote":"gauche"},{"nom":"Max","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Eva","texte":"Wohin stelle ich die Lampe?"},{"qui":"Max","texte":"Stell sie bitte auf den Schreibtisch. Die Pflanze steht schon neben dem Fenster."},{"qui":"Eva","texte":"Und der Teppich? Ich lege ihn vor das Sofa."},{"qui":"Max","texte":"Gut. Dann sitzt die Katze bald auf dem Teppich."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux articles au datif : ils répondent à « wo ? ».","aide":"Ils décrivent un état, pas un mouvement.","type":"zone","document":"umzug","multiple":true},{"enonce":"Range chaque verbe : action (accusatif) ou état (datif) ?","aide":"Les verbes en *-en* qui commencent par *st-*, *l-*, *s-* vont par paires : un pour l’action, un pour l’état.","type":"categories","categories":[{"id":"c0","texte":"Action → accusatif (wohin ?)"},{"id":"c1","texte":"État → datif (wo ?)"}],"items":[{"id":"i0","texte":"stehen"},{"id":"i1","texte":"legen"},{"id":"i2","texte":"stellen"},{"id":"i3","texte":"sitzen"},{"id":"i4","texte":"setzen"},{"id":"i5","texte":"liegen"}]},{"enonce":"Complète : « Je pose le livre sur la table. Le livre est sur la table. »","aide":"Premier trou : action (*legen*) ; deuxième trou : état (*liegen*).","type":"trous","segments":["Ich ",0," das Buch auf den Tisch. Das Buch ",1," auf dem Tisch."],"banque":["legt","lege","liege","liegt"]},{"enonce":"Associe chaque forme pleine à sa contraction.","aide":"*das* devient *-s*, *dem* devient *-m*.","type":"association","gauche":[{"id":"g0","texte":"in das"},{"id":"g1","texte":"in dem"},{"id":"g2","texte":"an dem"},{"id":"g3","texte":"auf das"}],"droite":[{"id":"d0","texte":"am"},{"id":"d1","texte":"im"},{"id":"d2","texte":"aufs"},{"id":"d3","texte":"ins"}]},{"enonce":"Remets en ordre : « J’assieds l’enfant sur la chaise. » La phrase commence par Ich.","aide":"*setzen* indique un mouvement : accusatif.","type":"ordre","items":[{"id":"a","texte":"das Kind"},{"id":"b","texte":"auf den Stuhl"},{"id":"c","texte":"Ich"},{"id":"d","texte":"setze"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16","m34"]},"explication":"**dem** (deux fois) : *neben dem Fenster* (où la plante se trouve) et *auf dem Teppich* (où la chatte sera) sont des lieux : datif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0","i5":"c1"}},"explication":"*stellen / legen / setzen* décrivent une **action** (on déplace quelque chose : accusatif) ; *stehen / liegen / sitzen* décrivent un **état** (datif)."},{"cle":{"type":"trous","trous":[["lege"],["liegt"]]},"affichage":"lege · liegt","explication":"**Ich lege** (action, accusatif : *auf den Tisch*) puis **liegt** (état, datif : *auf dem Tisch*)."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"*in das → ins*, *in dem → im*, *an dem → am*, *auf das → aufs*."},{"cle":{"type":"ordre","ids":["c","d","a","b"]},"explication":"**Ich setze das Kind auf den Stuhl.** *setzen* (action) appelle *auf* + accusatif."}]$ex$::jsonb),
  ('8479055b-1fb7-55b1-a35f-5009eb9f76bd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Emménager, étape par étape","competence":"raisonner","situation":"Anna décrit sa nouvelle chambre dans une lettre ; elle échange aussi des messages avec son père, qui déplace les meubles. Il faut dire à chaque fois s’il y a mouvement ou non.","documents":[{"id":"brief","type":"texte","genre":"lettre","titre":"Hallo Mia","blocs":["Heute ziehe ich um! Das Sofa steht jetzt im Wohnzimmer. Den Tisch stelle ich vor das Fenster. Neben dem Sofa liegt der Teppich. Über dem Tisch hängt die Lampe. Morgen hänge ich ein Bild an die Wand."],"source":"Lettre écrite pour l’exercice"},{"id":"papa","type":"dialogue","modele":"sms","titre":"Mit Papa","participants":[{"nom":"Papa","emoji":"👧","cote":"gauche"},{"nom":"Anna","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Papa","texte":"Wo soll ich den Schrank hinstellen?"},{"qui":"Anna","texte":"Stell ihn neben die Tür."},{"qui":"Papa","texte":"Er steht jetzt neben der Tür. Und die Kisten?"},{"qui":"Anna","texte":"Leg sie unter das Bett. Dann liegen sie sicher unter dem Bett."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les deux prépositions qui expriment un déplacement : elles sont suivies de l’accusatif.","aide":"Anna pose ou accroche quelque chose quelque part.","type":"zone","document":"brief","multiple":true},{"enonce":"Touche les trois prépositions qui expriment un lieu : elles sont suivies du datif.","aide":"Le sofa, le tapis et la lampe sont déjà en place.","type":"zone","document":"brief","multiple":true},{"enonce":"Range chaque phrase du dialogue : mouvement (wohin ?) ou lieu (wo ?).","aide":"Repère le verbe : *stellen* et *legen* disent un geste, *stehen* et *liegen* un état.","type":"categories","categories":[{"id":"c0","texte":"Mouvement → accusatif (wohin ?)"},{"id":"c1","texte":"Lieu → datif (wo ?)"}],"items":[{"id":"i0","texte":"Er steht jetzt neben der Tür."},{"id":"i1","texte":"Sie liegen unter dem Bett."},{"id":"i2","texte":"Leg sie unter das Bett."},{"id":"i3","texte":"Stell ihn neben die Tür."}]},{"enonce":"Complète : « Papa pose l’armoire à côté de la porte. Maintenant elle est à côté de la porte. »","aide":"Premier trou : action ; deuxième trou : état.","type":"trous","segments":["Papa ",0," den Schrank neben die Tür. Jetzt ",1," er neben der Tür."],"banque":["stehen","steht","stellt","stelle"]},{"enonce":"Remets en ordre : « Je mets les caisses sous le lit. » La phrase commence par Ich.","aide":"Il y a un mouvement : accusatif.","type":"ordre","items":[{"id":"a","texte":"Ich"},{"id":"b","texte":"die Kisten"},{"id":"c","texte":"lege"},{"id":"d","texte":"unter das Bett"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m34"]},"explication":"**vor** (*stelle ich vor das Fenster*) et **an** (*hänge ich an die Wand*) expriment un mouvement : accusatif."},{"cle":{"type":"zone","ids":["m8","m17","m23"]},"explication":"**im** (= *in dem*), **Neben** et **Über** décrivent où sont les objets : datif."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"*Stell ihn neben die Tür* et *Leg sie unter das Bett* : mouvement, accusatif (*die*, *das*). *steht neben der Tür* et *liegen unter dem Bett* : lieu, datif (*der*, *dem*)."},{"cle":{"type":"trous","trous":[["stellt"],["steht"]]},"affichage":"stellt · steht","explication":"**stellt** (action, avec accusatif : *neben die Tür*) puis **steht** (état, avec datif : *neben der Tür*)."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**Ich lege die Kisten unter das Bett.** *legen* + *unter* + accusatif."}]$ex$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Sur le parking de l’école","competence":"comprendre-langue","situation":"Le journal de l’école décrit les véhicules garés devant le lycée. Les propriétaires sont indiqués de deux manières différentes.","documents":[{"id":"park","type":"texte","genre":"article","titre":"Auf dem Parkplatz","blocs":["Auf dem Parkplatz stehen drei Fahrzeuge. Peters Auto ist blau, Annas Roller ist rot. Das Auto des Lehrers ist schwarz."],"source":"Article écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux génitifs saxons : le nom du possesseur est devant, avec un -s.","aide":"Ce sont des prénoms, sans article.","type":"zone","document":"park","multiple":true},{"enonce":"Touche l’article qui introduit un génitif ordinaire, placé derrière le nom.","aide":"Cet article est suivi d’un nom masculin avec -s.","type":"zone","document":"park","multiple":false},{"enonce":"Complète : « la maison du père et la chambre de la mère ».","aide":"Masculin et neutre : *des* ; féminin et pluriel : *der*.","type":"trous","segments":["Das Haus ",0," Vaters und das Zimmer ",1," Mutter."],"banque":["der","den","des","dem"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6","m10"]},"explication":"**Peters** et **Annas** : le génitif saxon se place devant le nom, avec **-s** et sans apostrophe ni article."},{"cle":{"type":"zone","ids":["m16"]},"explication":"**des** : *das Auto des Lehrers*. Le possesseur est derrière, avec l’article au génitif (*des*) et un **-s** au nom."},{"cle":{"type":"trous","trous":[["des"],["der"]]},"affichage":"des · der","explication":"**des Vaters** (masculin : *des* + nom en -s) et **der Mutter** (féminin : *der*, le nom ne change pas)."}]$ex$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"À qui est ce vélo ?","competence":"manier-langue","situation":"Lena veut savoir à qui appartiennent un téléphone et un vélo. Tom répond de trois manières différentes.","documents":[{"id":"wem","type":"dialogue","modele":"sms","titre":"Wessen Handy?","participants":[{"nom":"Lena","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lena","texte":"Wessen Handy liegt da?"},{"qui":"Tom","texte":"Das ist das Handy von meinem Bruder."},{"qui":"Lena","texte":"Und das Fahrrad vor der Tür?"},{"qui":"Tom","texte":"Das ist Annas Fahrrad. Es bleibt wegen des Regens hier."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition de la tournure orale « de + datif » : le possesseur est derrière.","aide":"Elle introduit « mon frère ».","type":"zone","document":"wem","multiple":false},{"enonce":"Touche le génitif saxon : le possesseur est devant le nom, sans article.","aide":"C’est un prénom terminé par -s.","type":"zone","document":"wem","multiple":false},{"enonce":"Touche la préposition qui régit le génitif et veut dire « à cause de ».","aide":"Elle est suivie de *des Regens*.","type":"zone","document":"wem","multiple":false},{"enonce":"Range chaque tournure selon sa construction.","aide":"Regarde où se trouve le possesseur et s’il y a un *von*.","type":"categories","categories":[{"id":"c0","texte":"Génitif saxon"},{"id":"c1","texte":"Génitif ordinaire"},{"id":"c2","texte":"von + datif"}],"items":[{"id":"i0","texte":"Lenas Tasche"},{"id":"i1","texte":"das Auto von meinem Vater"},{"id":"i2","texte":"das Auto des Vaters"},{"id":"i3","texte":"die Tasche der Frau"},{"id":"i4","texte":"Peters Auto"},{"id":"i5","texte":"die Tasche von meiner Mutter"}]},{"enonce":"Complète : « Pendant l’été, nous allons à la mer. »","aide":"Le sens est « pendant » : une durée.","type":"trous","segments":[0," des Sommers fahren wir ans Meer."],"banque":["Wegen","Während","Statt","Trotz"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**von** : *das Handy von meinem Bruder* est la tournure orale, avec un datif."},{"cle":{"type":"zone","ids":["m19"]},"explication":"**Annas** : *Annas Fahrrad*, sans article et sans apostrophe."},{"cle":{"type":"zone","ids":["m23"]},"explication":"**wegen** : *wegen des Regens*. Les prépositions *wegen*, *trotz*, *während*, *statt* régissent le génitif."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c1","i4":"c0","i5":"c2"}},"explication":"Le **génitif saxon** met le possesseur devant (*Lenas Tasche*), le **génitif ordinaire** derrière avec *des* ou *der*, et *von* + datif est la forme orale."},{"cle":{"type":"trous","trous":[["wahrend"]]},"affichage":"Während","explication":"**Während des Sommers** : *während* + génitif veut dire « pendant »."}]$ex$::jsonb),
  ('8c3bf0b0-bf2d-5cbb-ac85-dd6466cb04f1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le journal du quartier","competence":"analyser-texte","situation":"Le journal du quartier raconte les travaux de l’été. Son vocabulaire est celui de l’écrit soigné : il utilise des prépositions suivies du génitif.","documents":[{"id":"viertel","type":"texte","genre":"article","titre":"Bei uns im Viertel","blocs":["Während des Sommers war die Straße gesperrt. Trotz der Hitze arbeiteten die Männer jeden Tag. Statt des alten Marktes gibt es jetzt einen Parkplatz.","Der Bürgermeister war nicht da, wegen seiner Krankheit."],"source":"Article écrit pour l’exercice"},{"id":"tabgen","type":"tableau","titre":"L’article et le nom au génitif","colonnes":["Genre","Article","Le nom"],"lignes":[["Masculin","des","prend -(e)s"],["Neutre","des","?"],["Féminin","der","?"],["Pluriel","der","?"]],"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions qui régissent le génitif.","aide":"Le sens est : pendant, malgré, au lieu de, à cause de.","type":"zone","document":"viertel","multiple":true},{"enonce":"Touche les deux noms féminins au génitif.","aide":"Leur article est *der*, ou le possessif *seiner*.","type":"zone","document":"viertel","multiple":true},{"enonce":"Complète d’après le tableau : « pendant l’année » (*das Jahr*).","aide":"Le nom neutre prend -(e)s au génitif, comme le masculin.","type":"trous","segments":["während des ",0],"banque":["Jahres","Jahre","Jahr","Jahren"]},{"enonce":"Associe chaque préposition à son sens.","aide":"Cherche la phrase du journal où chaque mot est utilisé.","type":"association","gauche":[{"id":"g0","texte":"wegen"},{"id":"g1","texte":"trotz"},{"id":"g2","texte":"während"},{"id":"g3","texte":"statt"}],"droite":[{"id":"d0","texte":"au lieu de"},{"id":"d1","texte":"à cause de"},{"id":"d2","texte":"malgré"},{"id":"d3","texte":"pendant"}]},{"enonce":"Remets en ordre : « À cause de la pluie, je reste à la maison. » La phrase commence par Wegen des Regens.","aide":"Le groupe prépositionnel est en première position : le verbe passe devant le sujet.","type":"ordre","items":[{"id":"a","texte":"Wegen des Regens"},{"id":"b","texte":"ich"},{"id":"c","texte":"bleibe"},{"id":"d","texte":"zu Hause"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m7","m15","m29"]},"explication":"**Während**, **Trotz**, **Statt** et **wegen** régissent le génitif."},{"cle":{"type":"zone","ids":["m9","m31"]},"explication":"**Hitze** et **Krankheit** sont féminins : au génitif, le nom ne prend aucune marque (*der Hitze*, *seiner Krankheit*)."},{"cle":{"type":"trous","trous":[["jahres"]]},"affichage":"Jahres","explication":"**während des Jahres** : au génitif, le nom masculin ou neutre prend **-(e)s** ; le féminin et le pluriel ne changent pas."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"*wegen* = à cause de, *trotz* = malgré, *während* = pendant, *statt* = au lieu de."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**Wegen des Regens bleibe ich zu Hause.** Le groupe en tête occupe la première place ; le verbe reste en deuxième, avant *ich*."}]$ex$::jsonb),
  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 1, 1, 5, 20, 3,
