  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les petites annonces de Lukas","competence":"manier-langue","situation":"Lukas vide sa chambre et publie une annonce. Il doit choisir la bonne terminaison pour chaque adjectif.","documents":[{"id":"kleinanz","type":"texte","genre":"article","titre":"Zu verkaufen","blocs":["Verkaufe meinen alten Computer, einen schnellen Drucker und gute Bücher. Dazu gibt es frische Eier vom Bauernhof."],"source":"Annonce écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux adjectifs employés sans déterminant (déclinaison forte).","aide":"Cherche les adjectifs qui précèdent directement un nom au pluriel.","type":"zone","document":"kleinanz","multiple":true},{"enonce":"Touche l’adjectif qui suit un possessif (« meinen »).","aide":"C’est un masculin à l’accusatif.","type":"zone","document":"kleinanz","multiple":false},{"enonce":"Range chaque groupe nominal selon sa déclinaison.","aide":"Regarde ce qui précède l’adjectif : article défini, article indéfini ou rien.","type":"categories","categories":[{"id":"c0","texte":"Faible (après der, die, das)"},{"id":"c1","texte":"Mixte (après ein, mein)"},{"id":"c2","texte":"Forte (sans déterminant)"}],"items":[{"id":"i0","texte":"alter Wein"},{"id":"i1","texte":"gute Freunde"},{"id":"i2","texte":"ein alter Mann"},{"id":"i3","texte":"mein neues Auto"},{"id":"i4","texte":"der alte Mann"},{"id":"i5","texte":"die neue Schule"}]},{"enonce":"Complète avec la bonne forme : « C’est une haute montagne et une voiture chère. »","aide":"*hoch* perd son c ; *teuer* perd son e devant une terminaison.","type":"trous","segments":["Das ist ein ",0," Berg und ein ",1," Auto."],"banque":["teures","hoher","hohes","teueres","hocher"]}]}$ex$::jsonb,
