  ('94371d4d-0c80-5235-a5b4-d9764ea8a9c0'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ma nouvelle chambre : lettre et grille","competence":"manier-langue","situation":"Mia emménage dans un nouveau logement. Elle décrit sa chambre à une amie, puis révise la déclinaison faible avec un tableau.","documents":[{"id":"zimmer","type":"texte","genre":"lettre","titre":"Hallo Mia","blocs":["Mein neues Zimmer ist toll! Ein großes Bett steht am Fenster. Neben dem alten Schrank hängt ein rosa Poster. Auf dem Tisch liegt ein dunkles Heft."],"source":"Lettre écrite pour l’exercice"},{"id":"tabdekl","type":"tableau","titre":"La déclinaison faible","colonnes":["Cas","Masculin","Féminin","Neutre","Pluriel"],"lignes":[["Nominatif","der alte Mann","die alte Frau","das alte Haus","die alten Kinder"],["Accusatif","den alten Mann","?","?","die alten Kinder"],["Datif","dem alten Mann","der alten Frau","?","?"]],"enteteLignes":true,"source":"Tableau écrit pour l’exercice"}],"questions":[{"enonce":"Touche l’adjectif qui ne prend jamais de terminaison.","aide":"C’est une couleur empruntée.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Touche l’adjectif qui a perdu un e pour recevoir sa terminaison.","aide":"Compare avec *dunkel*.","type":"zone","document":"zimmer","multiple":false},{"enonce":"Pourquoi « ein großes Bett », mais « eine große Lampe » ?","aide":"Compare la terminaison de *ein* et celle de *eine*.","type":"choix","options":[{"id":"a","texte":"Après ein, l’adjectif prend toujours la forme -en"},{"id":"b","texte":"Bett est féminin, l’adjectif prend donc un -e"},{"id":"c","texte":"Ein ne marque pas le neutre, l’adjectif le fait"},{"id":"d","texte":"Groß est un attribut, donc il se décline ici"}],"multiple":false},{"enonce":"Complète les cases du tableau : accusatif féminin et accusatif neutre.","aide":"À l’accusatif, féminin et neutre ressemblent au nominatif.","type":"trous","segments":["die ",0," Frau · das ",1," Haus"],"banque":["altes","alter","alte","alten"]},{"enonce":"Complète les cases du datif : le neutre, puis le pluriel.","aide":"Au datif, l’adjectif faible prend la même terminaison partout.","type":"trous","segments":["dem ",0," Haus · den ",1," Kindern"],"banque":["alten","alter","altes","alte"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"**rosa** est invariable, comme *lila* : *ein rosa Poster*."},{"cle":{"type":"zone","ids":["m24"]},"explication":"**dunkles** : *dunkel* perd son *e* devant une terminaison (*ein dunkles Heft*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"*ein* est sans marque au neutre : l’adjectif porte **-es**. *eine* marque déjà le féminin : l’adjectif se contente de **-e**."},{"cle":{"type":"trous","trous":[["alte"],["alte"]]},"affichage":"alte · alte","explication":"**die alte Frau**, **das alte Haus** : à l’accusatif, le féminin et le neutre gardent le **-e** du nominatif."},{"cle":{"type":"trous","trous":[["alten"],["alten"]]},"affichage":"alten · alten","explication":"**dem alten Haus**, **den alten Kindern** : au datif (et au génitif), la terminaison faible est toujours **-en**."}]$ex$::jsonb),
  ('9712f7b8-159d-5a85-b792-992b0ea096f4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un samedi chargé pour Lena","competence":"comprendre-langue","situation":"Mia veut voir Lena ce week-end. Lena lui répond par SMS et donne ses horaires : à toi de repérer comment elle dit le temps.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Samstag","participants":[{"nom":"Mia","emoji":"👧","cote":"gauche"},{"nom":"Lena","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Mia","texte":"Hast du am Samstag Zeit?"},{"qui":"Lena","texte":"Nur am Nachmittag. Um zehn Uhr habe ich Training."},{"qui":"Mia","texte":"Und im Juli? Fährst du weg?"},{"qui":"Lena","texte":"Ja, im Juli fahre ich zu meiner Oma."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui donne l’heure précise du Training.","aide":"C’est le petit mot placé juste devant « zehn Uhr ».","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces compléments de temps selon la préposition qui leur convient.","aide":"Jours et moments de la journée : am. Mois et saisons : im. Heures précises : um.","type":"categories","categories":[{"id":"c0","texte":"am"},{"id":"c1","texte":"im"},{"id":"c2","texte":"um"}],"items":[{"id":"i0","texte":"Januar"},{"id":"i1","texte":"Mitternacht"},{"id":"i2","texte":"acht Uhr"},{"id":"i3","texte":"Sommer"},{"id":"i4","texte":"Montag"},{"id":"i5","texte":"Abend"}]},{"enonce":"Lena propose : « Je suis libre le samedi après-midi. » Complète.","aide":"Samstagnachmittag est un moment précis d’un jour.","type":"trous","segments":["Ich habe ",0," Samstagnachmittag Zeit."],"banque":["im","am","in","um"]}]}$ex$::jsonb,
