  ('9712f7b8-159d-5a85-b792-992b0ea096f4'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une lettre de Vienne","competence":"analyser-texte","situation":"Jonas passe quelques jours à Vienne et écrit à sa correspondante Paula. Son courrier est plein de repères de temps.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Liebe Paula","blocs":["Liebe Paula, vor zwei Wochen habe ich meine Reise geplant, und jetzt bin ich in Wien! Ich bleibe von Montag bis Freitag. Morgens gehe ich ins Museum, abends esse ich mit Freunden. In einer Woche bin ich wieder zu Hause. Bis bald! Jonas"],"source":"Courrier écrit pour l’exercice"}],"questions":[{"enonce":"Touche les deux petits mots qui disent « du lundi au vendredi ».","aide":"Cherche une préposition de départ et une préposition d’arrivée autour des jours.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche les deux adverbes qui disent ce que Jonas fait d’habitude, le matin et le soir.","aide":"Ils se terminent par un -s et décrivent une habitude.","type":"zone","document":"lettre","multiple":true},{"enonce":"Que dit Jonas dans « In einer Woche bin ich wieder zu Hause » ?","aide":"Pense au futur : *in* + datif exprime un moment à venir.","type":"choix","options":[{"id":"a","texte":"Il rentre dans une semaine"},{"id":"b","texte":"Il rentre depuis une semaine"},{"id":"c","texte":"Il est rentré il y a une semaine"},{"id":"d","texte":"Il rentre pour une semaine"}],"multiple":false},{"enonce":"Associe chaque expression de temps à sa traduction.","aide":"Vor = passé, in = futur, seit = depuis, während = pendant.","type":"association","gauche":[{"id":"g0","texte":"vor zwei Wochen"},{"id":"g1","texte":"in zwei Wochen"},{"id":"g2","texte":"seit zwei Wochen"},{"id":"g3","texte":"während der Ferien"}],"droite":[{"id":"d0","texte":"dans deux semaines"},{"id":"d1","texte":"depuis deux semaines"},{"id":"d2","texte":"pendant les vacances"},{"id":"d3","texte":"il y a deux semaines"}]}]}$ex$::jsonb,
