aut une préposition de départ et une préposition d’arrivée.","type":"trous","segments":["Der Austausch dauert ",0," Montag ",1," Freitag."],"banque":["bis","von","ab","seit"]},{"enonce":"Touche la préposition qui dit que Lisa attend « depuis » dix minutes.","aide":"Cette préposition est suivie du datif et, en allemand, le verbe reste au présent.","type":"zone","document":"sms","multiple":false},{"enonce":"Que signifie « Wir sind in fünf Minuten da » ?","aide":"Pour parler de l’avenir, l’allemand dit *in* + datif.","type":"choix","options":[{"id":"a","texte":"Nous serons là dans cinq minutes"},{"id":"b","texte":"Nous sommes là depuis cinq minutes"},{"id":"c","texte":"Nous étions là il y a cinq minutes"},{"id":"d","texte":"Nous sommes là pendant cinq minutes"}],"multiple":false}]}$ex$::jsonb,
