  ('8ac8fba3-6ef4-59d4-b1bf-8840c1cacf0c'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale de Vienne","competence":"manier-langue","situation":"Mia est en voyage à Vienne et écrit à sa grand-mère. Elle décrit la ville, les gens et le temps.","documents":[{"id":"wien","type":"texte","genre":"lettre","titre":"Liebe Oma","blocs":["Wir sind jetzt in Wien. Die Stadt ist groß und die Leute sind freundlich. Das Wetter bleibt schön. Mein Bruder hat ein neues Fahrrad."],"source":"Carte postale écrite pour l’exercice"}],"questions":[{"enonce":"Touche les trois adjectifs attributs, ceux qui suivent « ist », « sind » ou « bleibt ».","aide":"Ils viennent après le verbe, pas devant un nom.","type":"zone","document":"wien","multiple":true},{"enonce":"Complète : « Les enfants sont fatigués. »","aide":"Après *sein*, l’adjectif ne change pas.","type":"trous","segments":["Die Kinder sind ",0,"."],"banque":["müder","müden","müdes","müde"]},{"enonce":"Pourquoi écrit-on « Die Stadt ist groß » et non « große » ?","aide":"Pense à la place de l’adjectif par rapport au verbe.","type":"choix","options":[{"id":"a","texte":"Groß est un attribut, donc il se décline"},{"id":"b","texte":"Après sein, l’adjectif attribut reste invariable"},{"id":"c","texte":"Stadt est féminin, il faut donc un -e"},{"id":"d","texte":"Après ist, l’adjectif prend toujours -en"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m13","m17"]},"explication":"**groß**, **freundlich** et **schön** sont attributs : ils suivent *sein* ou *bleiben*. *neues* est épithète, devant *Fahrrad*."},{"cle":{"type":"trous","trous":[["mude"]]},"affichage":"müde","explication":"**Die Kinder sind müde.** L’adjectif attribut reste à sa forme nue, même avec un sujet au pluriel."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Après *sein*, *werden* et *bleiben*, l’adjectif attribut ne se décline jamais.** Le français accorde (« grande »), l’allemand non."}]$ex$::jsonb),
