  ('ae0a3bfb-73a9-554f-95a1-d5ea673e88af'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où est Mara ?","competence":"manier-langue","situation":"Lukas cherche Mara, qui enchaîne plusieurs rendez-vous. Dans leurs messages, plusieurs prépositions sont contractées avec l’article.","documents":[{"id":"mara","type":"dialogue","modele":"sms","titre":"Wo bist du?","participants":[{"nom":"Lukas","emoji":"👧","cote":"gauche"},{"nom":"Mara","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lukas","texte":"Wo bist du?"},{"qui":"Mara","texte":"Ich bin beim Arzt. Danach gehe ich zur Apotheke und dann zum Bahnhof."},{"qui":"Lukas","texte":"Kommst du vom Arzt direkt zu mir?"},{"qui":"Mara","texte":"Nein, erst nach dem Essen."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche les quatre prépositions contractées avec l’article.","aide":"Elles se terminent par -m ou -r et remplacent *bei dem*, *zu der*, *zu dem*, *von dem*.","type":"zone","document":"mara","multiple":true},{"enonce":"Associe chaque forme pleine à sa contraction.","aide":"Garde la même préposition et fusionne-la avec l’article.","type":"association","gauche":[{"id":"g0","texte":"zu der"},{"id":"g1","texte":"zu dem"},{"id":"g2","texte":"bei dem"},{"id":"g3","texte":"von dem"}],"droite":[{"id":"d0","texte":"zum"},{"id":"d1","texte":"beim"},{"id":"d2","texte":"zur"},{"id":"d3","texte":"vom"}]},{"enonce":"Complète : « Nous allons à la piscine. »","aide":"*Schwimmbad* est neutre.","type":"trous","segments":["Wir gehen ",0," Schwimmbad."],"banque":["zum","beim","vom","zur"]},{"enonce":"Remets en ordre : « Après le repas, je vais à la pharmacie. » La phrase commence par Nach dem Essen.","aide":"Le groupe de temps est en tête, donc le verbe passe avant le sujet.","type":"ordre","items":[{"id":"a","texte":"zur Apotheke"},{"id":"b","texte":"Nach dem Essen"},{"id":"c","texte":"gehe"},{"id":"d","texte":"ich"}]}]}$ex$::jsonb,
