  ('ae0a3bfb-73a9-554f-95a1-d5ea673e88af'::uuid, 3, 3, 15, 50, 6,
   $ex${"titre":"Une carte postale de Vienne et de Suisse","competence":"argumenter","situation":"Jana prépare un voyage en Autriche puis en Suisse. Elle l’annonce à sa grand-mère et lui répond au sujet de son allemand.","documents":[{"id":"reise","type":"texte","genre":"lettre","titre":"Hallo Oma","blocs":["Morgen fahre ich mit dem Zug nach Wien. Am Samstag fliege ich in die Schweiz, zu meinem Onkel. Ich bleibe bei ihm bis Montag. Die Schokolade für dich ist aus der Schweiz."],"source":"Lettre écrite pour l’exercice"},{"id":"oma","type":"dialogue","modele":"sms","titre":"Oma fragt","participants":[{"nom":"Oma","emoji":"👧","cote":"gauche"},{"nom":"Jana","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Oma","texte":"Wie lange lernst du schon Deutsch?"},{"qui":"Jana","texte":"Ich lerne seit zwei Jahren Deutsch."}],"source":"Messages écrits pour l’exercice"}],"questions":[{"enonce":"Touche la préposition qui précède une ville sans article.","aide":"Wien est un nom de ville.","type":"zone","document":"reise","multiple":false},{"enonce":"Touche la préposition employée devant un pays avec article.","aide":"*die Schweiz* a un article.","type":"zone","document":"reise","multiple":false},{"enonce":"Touche la préposition qui précède une personne comme but du voyage.","aide":"Elle est suivie de *meinem Onkel*.","type":"zone","document":"reise","multiple":false},{"enonce":"Complète : « Je vais à Berlin, en Turquie et chez ma tante. »","aide":"Ville sans article, pays avec article, personne : trois prépositions différentes.","type":"trous","segments":["Ich fahre ",0," Berlin, ",1," die Türkei und ",2," meiner Tante."],"banque":["zu","aus","in","nach","bei"]},{"enonce":"Touche la préposition qui exprime « depuis » dans la réponse de Jana.","aide":"Elle est devant « zwei Jahren ».","type":"zone","document":"oma","multiple":false},{"enonce":"Comment dit-on « Je connais Marie depuis deux ans » ?","aide":"Comme dans la réponse de Jana, un fait qui dure encore s’exprime avec le même temps.","type":"choix","options":[{"id":"a","texte":"Ich werde Marie seit zwei Jahren kennen"},{"id":"b","texte":"Ich habe Marie seit zwei Jahren gekannt"},{"id":"c","texte":"Ich kenne Marie seit zwei Jahren"},{"id":"d","texte":"Ich kannte Marie seit zwei Jahren"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**nach** : *nach Wien*. Les villes et les pays sans article se disent avec *nach*."},{"cle":{"type":"zone","ids":["m12"]},"explication":"**in** : *in die Schweiz* (accusatif). Un pays avec article demande *in* + accusatif."},{"cle":{"type":"zone","ids":["m15"]},"explication":"**zu** : *zu meinem Onkel*. Pour aller chez quelqu’un, on emploie *zu* + datif."},{"cle":{"type":"trous","trous":[["nach"],["in"],["zu"]]},"affichage":"nach · in · zu","explication":"**nach Berlin** (ville sans article), **in die Türkei** (pays avec article, accusatif), **zu meiner Tante** (personne, datif)."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**seit** : *seit zwei Jahren* = « depuis deux ans », avec un datif."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Ich kenne Marie seit zwei Jahren** : avec *seit*, l’allemand emploie le **présent** pour une situation qui dure encore."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 1re (1) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
